      {/* Script to animate traveling white dot back and forth ("edar odar") smoothly */}
      <script>{`
        (function() {
          function runFlightDot() {
            var path = document.getElementById('flightArcTrajectory');
            var dot = document.getElementById('flightTravelingDot');
            var halo = document.getElementById('flightTravelingHalo');
            if (!path || !dot || path.__flightAnimated) return;
            path.__flightAnimated = true;
            var totalLen = path.getTotalLength();
            var progress = 0;
            var forward = true;
            var speed = 0.0035;

            function step() {
              if (!document.getElementById('flightArcTrajectory')) return;

              if (forward) {
                progress += speed;
                if (progress >= 1) {
                  progress = 1;
                  forward = false; // reached Islamabad -> reverse back to London!
                }
              } else {
                progress -= speed;
                if (progress <= 0) {
                  progress = 0;
                  forward = true; // reached London -> travel to Islamabad!
                }
              }

              // Smooth ease-in-out easing
              var eased = progress < 0.5 
                ? 2 * progress * progress 
                : 1 - Math.pow(-2 * progress + 2, 2) / 2;

              var pt = path.getPointAtLength(eased * totalLen);
              dot.setAttribute('cx', pt.x.toFixed(1));
              dot.setAttribute('cy', pt.y.toFixed(1));
              if (halo) {
                halo.setAttribute('cx', pt.x.toFixed(1));
                halo.setAttribute('cy', pt.y.toFixed(1));
                halo.setAttribute('fill', progress < 0.5 ? '#38bdf8' : '#fb923c');
              }
              requestAnimationFrame(step);
            }
            requestAnimationFrame(step);
          }

          if (document.readyState === 'loading') {
            document.addEventListener('DOMContentLoaded', runFlightDot);
          } else {
            runFlightDot();
          }
          setTimeout(runFlightDot, 50);
          setTimeout(runFlightDot, 300);
        })();
      `}</script>
